/** Shared interface translations. Proper names, soundtrack titles and player text stay unchanged. */
import { PIDGIN_TRANSLATIONS } from './pidgin';
export type Locale = 'en' | 'es' | 'fr' | 'zh-CN' | 'ja' | 'pcm';

export const SUPPORTED_LOCALES: readonly Readonly<{ value: Locale; label: string }>[] = Object.freeze(([
  { value: 'en', label: 'English' },
  { value: 'es', label: 'Español' },
  { value: 'fr', label: 'Français' },
  { value: 'zh-CN', label: '简体中文' },
  { value: 'ja', label: '日本語' },
  { value: 'pcm', label: 'Nigerian Pidgin' },
] satisfies { value: Locale; label: string }[]).map(locale => Object.freeze(locale)));

export function normalizeLocale(value: unknown): Locale {
  if (typeof value !== 'string') return 'en';
  const tag = value.toLowerCase().replace('_', '-');
  if (tag === 'zh' || tag === 'zh-cn' || tag === 'zh-hans' || tag.startsWith('zh-hans-')) return 'zh-CN';
  const base = tag.split('-')[0];
  return base === 'es' || base === 'fr' || base === 'ja' || base === 'pcm' ? base : 'en';
}

