const localeIndex: Record<Exclude<Locale, 'en' | 'pcm'>, number> = { es: 0, fr: 1, 'zh-CN': 2, ja: 3 };
const lookup = new Map(Object.entries(MENU_TRANSLATIONS).map(([source, translations]) => [source.toLowerCase(), translations]));
const pidginLookup = new Map(Object.entries(PIDGIN_TRANSLATIONS).map(([source, translation]) => [source.toLowerCase(), translation]));

/** Bounded native-text atlas, including all language names used by the picker. */
export function localeCharset(locale: Locale): string {
  const ascii = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i)).join('');
  const localized = locale === 'en' ? '' : locale === 'pcm' ? Object.values(PIDGIN_TRANSLATIONS).join('') : Object.values(MENU_TRANSLATIONS).map(row => row[localeIndex[locale]]).join('');
  const text = ascii + Object.keys(MENU_TRANSLATIONS).join('') + localized + localized.toLocaleUpperCase(locale) + SUPPORTED_LOCALES.map(item => item.label).join('');
  return Array.from(new Set(Array.from(text))).filter(char => !/[\r\n\t]/.test(char)).join('');
}

/** Unknown source text is intentionally preserved, including user-authored text. */
export function translate(text: string, locale: Locale): string {
  if (locale === 'en' || !text) return text;
  const source = text.trim();
  const row = lookup.get(source.toLowerCase());
  if (!row) {
    const chapter = /^(Chapter|Arena) (\d+)$/.exec(source);
    if (chapter) {
      const noun = chapter[1] === 'Chapter'
        ? ({ es: 'Capítulo', fr: 'Chapitre', 'zh-CN': '章节', ja: 'チャプター', pcm: 'Chapter' } as const)[locale]
        : ({ es: 'Arena', fr: 'Arène', 'zh-CN': '竞技场', ja: 'アリーナ', pcm: 'Arena' } as const)[locale];
      return text.replace(source, `${noun} ${chapter[2]}`);
    }
    return text;
  }
  const translated = locale === 'pcm' ? pidginLookup.get(source.toLowerCase()) ?? source : row[localeIndex[locale]];
  const preserveCaps = /[A-Z]/.test(source) && source === source.toUpperCase();
  return text.replace(source, preserveCaps ? translated.toLocaleUpperCase(locale) : translated);
}
